probs = values(sheet, f'G390:G{398}')
from_states = values(sheet, f'H390:H{398}')
to_states = values(sheet, f'I390:I{398}')

trans = {}
for p, f, t in zip(probs, from_states, to_states):
    if f not in trans:
        trans[f] = {}
    trans[f][t] = p

states = ['Idle', 'Active', 'Done']
rewards = {'Idle': 0, 'Active': 2, 'Done': 7}

# Step 0: certainly Idle
dist = {'Idle': 1.0, 'Active': 0.0, 'Done': 0.0}

for step in range(3):
    next_dist = {'Idle': 0.0, 'Active': 0.0, 'Done': 0.0}
    for s in states:
        prob_s = dist[s]
        if prob_s > 0:
            for t in states:
                p_trans = trans.get(s, {}).get(t, 0.0)
                next_dist[t] += prob_s * p_trans
    dist = next_dist

result = sum(dist[s] * rewards[s] for s in states)

