import itertools
sheet = 'W1::Allowed assignments'
rows = data_rows(sheet, {'L': 'string', 'M': 'string', 'N': 'number'}, 812, 820)
tasks = list(set(cell(sheet, f'L{r}') for r in rows))
workers = list(set(cell(sheet, f'M{r}') for r in rows))
pairs = set((cell(sheet, f'L{r}'), cell(sheet, f'M{r}')) for r in rows)
max_cov = 0
for r in range(1, len(tasks) + 1):
    for p in itertools.permutations(workers, r):
        # try to match r tasks
        for t_sub in itertools.combinations(tasks, r):
            valid = True
            for t, w in zip(t_sub, p):
                if (t, w) not in pairs:
                    valid = False
                    break
            if valid:
                max_cov = max(max_cov, r)
result = max_cov

